img.ph.ph-photo{display:block;width:100%;height:auto;aspect-ratio:var(--ar,41/27);object-fit:cover;background:#F6F3FB}
.hero-bg img.ph.ph-photo{height:100%;aspect-ratio:auto}
.hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(252,251,250,.96) 0%,rgba(252,251,250,.88) 38%,rgba(252,251,250,.35) 70%,rgba(252,251,250,.1) 100%);pointer-events:none}
