  background:linear-gradient(135deg,#F4F0FA 0%,#EDF5FB 52%,#FDF1ED 100%)}
.nifty-part-footer-5 .band-in {position:relative;z-index:2;padding:60px 44px;text-align:center}
.nifty-part-footer-5 .band h2 {font-size:clamp(26px,3.4vw,40px);margin-bottom:16px}
