.nifty-part-footer-5 .built b {color:var(--butter);font-weight:700;letter-spacing:.01em}
.nifty-part-footer-5 .f-bar {background:var(--lilac);color:var(--charcoal);text-align:center;padding:14px 20px;
  font-size:13.5px;font-weight:500;display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:wrap}
.nifty-part-footer-5 .sticky {display:none}
.nifty-part-footer-5 .ty {max-width:680px;margin:0 auto;text-align:center;padding-top:70px;padding-bottom:70px}
.nifty-part-footer-5 .ty-mark {width:88px;height:88px;border-radius:50%;background:var(--mint);display:grid;place-items:center;
  margin:0 auto 26px;font-size:36px;color:var(--charcoal)}
.nifty-part-footer-5 .ty h1 {font-size:clamp(30px,4vw,44px);margin-bottom:16px}
