@media (max-width:1440px) {.nifty-part-footer-5 .nav a.top, .nifty-part-footer-5 .nav .drop-lbl {padding:10px 9px;font-size:13.4px}}
@media (max-width:1280px) {.nifty-part-footer-5 .burger {display:grid;place-items:center;width:44px;height:44px;border-radius:13px;
