    transition:clip-path .3s ease, opacity .25s ease;z-index:70}
.nifty-part-footer-5 .mtoggle:checked ~ .nav {clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
.nifty-part-footer-5 .nav>li {border-bottom:1px solid var(--line)}
.nifty-part-footer-5 .nav a.top, .nifty-part-footer-5 .nav .drop-lbl {padding:15px 4px;font-size:16px;font-weight:600;border-radius:0;justify-content:space-between}
.nifty-part-footer-5 .nav .caret {font-size:13px}
.nifty-part-footer-5 .menu {position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    border-radius:0;padding:0 0 12px;min-width:0;max-height:0;overflow:hidden;transition:max-height .3s ease}
.nifty-part-footer-5 .dtoggle:checked + .drop-lbl + .menu {max-height:900px}
.nifty-part-footer-5 .dtoggle:checked + .drop-lbl .caret {transform:rotate(180deg)}
.nifty-part-footer-5 .menu a {padding:9px 12px;font-size:14.6px;color:var(--muted)}
.nifty-part-footer-5 .nav-cta {display:flex!important;flex-direction:column;gap:11px;padding-top:22px;border:0!important}
.nifty-part-footer-5 .nav-cta .btn {width:100%}}
@media (max-width:1100px) {.nifty-part-footer-5 .hero-grid, .nifty-part-footer-5 .hero-split {grid-template-columns:minmax(0,1fr);gap:38px;padding-top:44px;padding-bottom:54px}
.nifty-part-footer-5 .hero-scrim {background:linear-gradient(180deg,rgba(250,249,246,.62) 0%,rgba(250,249,246,.93) 26%,rgba(250,249,246,.98) 100%)}
.nifty-part-footer-5 .hero-form {max-width:560px}
.nifty-part-footer-5 .t6 {grid-template-columns:repeat(3,minmax(0,1fr))}
.nifty-part-footer-5 .t4, .nifty-part-footer-5 .g3, .nifty-part-footer-5 .g4, .nifty-part-footer-5 .steps {grid-template-columns:repeat(2,minmax(0,1fr))}
.nifty-part-footer-5 .urg, .nifty-part-footer-5 .why {grid-template-columns:minmax(0,1fr)}
.nifty-part-footer-5 .urg-txt {padding:34px 30px 8px}
.nifty-part-footer-5 .urg-img .ph {min-height:240px}
.nifty-part-footer-5 .why-txt {padding:8px 32px 38px}
.nifty-part-footer-5 .why-img {order:-1}
.nifty-part-footer-5 .why-img .ph {min-height:260px}
.nifty-part-footer-5 .loc-grid {grid-template-columns:repeat(2,minmax(0,1fr))}
.nifty-part-footer-5 .strip .wrap {grid-template-columns:repeat(2,minmax(0,1fr))}
.nifty-part-footer-5 .f-top {grid-template-columns:repeat(3,minmax(0,1fr))}
.nifty-part-footer-5 .f-brand {grid-column:1/-1}
.nifty-part-footer-5 .legal {grid-template-columns:minmax(0,1fr);gap:28px}
.nifty-part-footer-5 .legal-toc {position:static}}
@media (max-width:768px) {.nifty-part-footer-5 {--gut:26px}
.nifty-part-footer-5 .sec {padding-top:60px;padding-bottom:60px}
.nifty-part-footer-5 .sec-tight {padding-top:48px;padding-bottom:48px}
.nifty-part-footer-5 {font-size:16px}
.nifty-part-footer-5 .nav {top:70px}
.nifty-part-footer-5 .hdr {min-height:70px}
.nifty-part-footer-5 .loc-band, .nifty-part-footer-5 .band-in {padding:32px 24px}
.nifty-part-footer-5 .sticky {display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(250,249,246,.97);backdrop-filter:blur(10px);border-top:1px solid var(--line);
    padding:10px 14px calc(10px + env(safe-area-inset-bottom))}
.nifty-part-footer-5 .sticky .btn {flex:1 1 0;min-width:0;padding:13px 12px;font-size:14.2px}
.nifty-part-footer-5 footer {padding-bottom:74px}}
@media (max-width:600px) {.nifty-part-footer-5 .t6, .nifty-part-footer-5 .t4, .nifty-part-footer-5 .t3, .nifty-part-footer-5 .g2, .nifty-part-footer-5 .g3, .nifty-part-footer-5 .g4, .nifty-part-footer-5 .steps, .nifty-part-footer-5 .loc-grid, .nifty-part-footer-5 .f-top {grid-template-columns:minmax(0,1fr)}
.nifty-part-footer-5 .strip .wrap {grid-template-columns:minmax(0,1fr);gap:14px}
.nifty-part-footer-5 .frow {grid-template-columns:minmax(0,1fr)}
.nifty-part-footer-5 .f-top {gap:26px}}
@media (max-width:430px) {.nifty-part-footer-5 {--gut:20px}
.nifty-part-footer-5 .card .cb, .nifty-part-footer-5 .step, .nifty-part-footer-5 .qform, .nifty-part-footer-5 .ty-next {padding:22px}
.nifty-part-footer-5 .brand-mark {width:34px;height:34px}
.nifty-part-footer-5 .brand-kids {font-size:15.5px}
.nifty-part-footer-5 .brand-sub {font-size:9.5px}
.nifty-part-footer-5 .cta-row .btn {width:100%}}
.nifty-part-footer-5{min-height:0 !important;height:auto !important;overflow:visible !important}

:root{
  --cloud:#E7E8EA; --sky:#BFD9EE; --peach:#F4B9A7; --butter:#F6D98A;
  --lilac:#D6C6E6; --mint:#C9E2D5; --white:#FAF9F6; --charcoal:#3E4145;
  --ink:#3E4145; --muted:#6B7076; --line:#E7E8EA;
  --sky-d:#4E87B0; --lilac-d:#9B84C2; --peach-d:#E28A6E; --mint-d:#5B9A7C; --butter-d:#A9821F;
  --sky-t:#356A91; --lilac-t:#6C5691; --peach-t:#B0522F; --mint-t:#3B7053; --butter-t:#77590C;
  --gut:40px; --r:20px; --rl:28px;
  --shadow:0 2px 4px rgba(62,65,69,.04), 0 10px 30px rgba(62,65,69,.07);
  --shadow-lg:0 4px 8px rgba(62,65,69,.05), 0 22px 55px rgba(62,65,69,.10);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);
  font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  font-size:16.5px;line-height:1.65;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:Poppins,Inter,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  font-weight:700;line-height:1.14;letter-spacing:-.02em;margin:0}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul{margin:0;padding:0;list-style:none}
:focus-visible{outline:3px solid var(--lilac-t);outline-offset:2px;border-radius:6px}
.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;
  clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:absolute;left:-9999px;top:0;z-index:200;background:var(--charcoal);color:#fff;
  padding:12px 20px;border-radius:0 0 12px 0;font-weight:600}
.skip:focus{left:0}

.wrap{width:100%;max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.wrap-n{max-width:960px}
.sec{padding-top:92px;padding-bottom:92px}
.sec-tight{padding-top:64px;padding-bottom:64px}
.eyebrow{font-family:Poppins,Inter,sans-serif;font-weight:600;font-size:12.5px;letter-spacing:.14em;
  text-transform:uppercase;color:var(--lilac-t);margin-bottom:14px}
.h2{font-size:clamp(28px,3.5vw,42px)}
.h3{font-size:clamp(21px,2.4vw,27px)}
.lead{color:var(--muted);font-size:17.5px;max-width:62ch}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.acc-lilac{color:var(--lilac-t)}.acc-peach{color:var(--peach-t)}.acc-sky{color:var(--sky-t)}
.sec-head{margin-bottom:36px}
.mt12{margin-top:12px}.mt14{margin-top:14px}.mt24{margin-top:24px}.mt34{margin-top:34px}

/* ---------- image placeholders (V6 3.12) ---------- */
.ph{position:relative;display:block;width:100%;aspect-ratio:var(--ar,41/27);
  background:repeating-linear-gradient(135deg,#F1F2F4 0 12px,#EAECEF 12px 24px);
  border:1px dashed #C8CCD2;border-radius:var(--r);overflow:hidden}
.ph-sq{--ar:1/1;border-radius:50%}
.ph-lab{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;
  justify-content:center;gap:3px;text-align:center;padding:14px;color:#5A6069}
.ph-lab b{font-family:Poppins,sans-serif;font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;
  color:#454A52}
.ph-lab span{font-size:11.5px;line-height:1.45;max-width:34ch}
.ph-lab code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10.5px;color:#6B7076}
.ph-lab i{font-size:19px;color:#AEB4BC;margin-bottom:4px}
body.prod .ph-lab{display:none}
.tile .ph,.card .ph,.pack .ph{border-radius:0;border-width:0 0 1px 0}

/* ---------- reveal ---------- */
.rv{animation:rvIn .8s both}
.rv2{animation-delay:.08s}.rv3{animation-delay:.16s}.rv4{animation-delay:.24s}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;
  font-family:Poppins,Inter,sans-serif;font-weight:600;font-size:15px;
  padding:14px 26px;border-radius:999px;border:2px solid transparent;cursor:pointer;
  transition:transform .18s ease, box-shadow .18s ease, background .18s ease;white-space:nowrap}
.btn:hover{transform:translateY(-2px)}
.btn i{font-size:.92em}
.btn-1{background:var(--peach);color:var(--charcoal);box-shadow:0 6px 18px rgba(244,185,167,.55)}
.btn-1:hover{background:#F7C7B7;box-shadow:0 10px 26px rgba(244,185,167,.65)}
.btn-2{background:var(--sky);color:var(--charcoal);box-shadow:0 6px 18px rgba(191,217,238,.55)}
.btn-2:hover{background:#D0E4F3}
.btn-3{background:transparent;color:var(--lilac-t);border-color:var(--lilac)}
.btn-3:hover{background:#F4F0FA}
.btn-w{background:#fff;color:var(--charcoal);border-color:var(--line)}
.btn-w:hover{background:#F7F5FB}
.btn-sm{padding:10px 20px;font-size:14px}
.btn-lg{padding:17px 34px;font-size:16.5px}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(250,249,246,.94);
  backdrop-filter:saturate(140%) blur(10px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:22px;min-height:78px}
.brand{display:flex;align-items:center;gap:11px;flex-shrink:0;min-width:0}
.brand-mark{width:38px;height:38px;flex-shrink:0}
.brand-txt{display:flex;flex-direction:column;line-height:1;min-width:0}
.brand-kids{font-family:Poppins,sans-serif;font-weight:700;font-size:17px;letter-spacing:.16em}
.brand-kids i{font-style:normal}
.brand-kids i:nth-child(1){color:var(--lilac-d)}
.brand-kids i:nth-child(2){color:#E5B94F}
.brand-kids i:nth-child(3){color:var(--peach-d)}
.brand-kids i:nth-child(4){color:var(--mint-d)}
.brand-sub{font-family:Poppins,sans-serif;font-weight:600;font-size:10.5px;letter-spacing:.19em;
  color:var(--charcoal);margin-top:4px}
.nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:6px;padding:10px 11px;border-radius:12px;
  font-family:Poppins,sans-serif;font-weight:500;font-size:14px;color:var(--charcoal);cursor:pointer;
  white-space:nowrap}
.nav-cta{display:none}
.nav a.top:hover,.nav .drop-lbl:hover,.nav a.top[aria-current="page"]{background:#F1EEF8;color:var(--lilac-t)}
.nav .caret{font-size:10px;flex-shrink:0;transition:transform .2s ease}
.menu{position:absolute;top:calc(100% + 10px);left:0;min-width:252px;background:#fff;
  border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-lg);padding:10px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.18s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 13px;border-radius:11px;font-size:14.2px;color:var(--charcoal)}
.menu a:hover{background:#F5F1FA;color:var(--lilac-t)}
.menu .mh{display:block;padding:8px 13px 4px;font-family:Poppins,sans-serif;font-weight:600;font-size:11px;
  letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.menu .msep{height:1px;background:var(--line);margin:8px 6px}
.hdr-act{display:flex;align-items:center;gap:12px;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- breadcrumb ---------- */
.bc{background:#F6F4FA;border-bottom:1px solid var(--line)}
.bc ol{display:flex;flex-wrap:wrap;align-items:center;gap:8px;list-style:none;margin:0;padding:13px 0;
  font-size:13px;color:var(--muted)}
.bc li{display:flex;align-items:center;gap:8px;min-width:0}
.bc li i{font-size:9px;color:#B4B9C0}
.bc a:hover{color:var(--lilac-t);text-decoration:underline}
.bc [aria-current="page"]{color:var(--charcoal);font-weight:600}

/* ---------- hero ---------- */
.hero{position:relative;overflow:hidden;
  background:linear-gradient(180deg,#F6F3FB 0%, #FBF6F4 46%, var(--white) 100%)}
.hero::before,.hero::after{content:"";position:absolute;border-radius:50%;pointer-events:none}
.hero::before{width:520px;height:520px;background:radial-gradient(circle,rgba(191,217,238,.42),transparent 68%);
  top:-190px;left:-160px}
.hero::after{width:560px;height:560px;background:radial-gradient(circle,rgba(214,198,230,.40),transparent 68%);
  bottom:-260px;right:-180px}
.hero-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);
  gap:52px;align-items:center;padding-top:66px;padding-bottom:74px}
.hero-solo{position:relative;z-index:2;padding-top:60px;padding-bottom:60px;max-width:74ch}
.hero-split{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);
  gap:48px;align-items:center;padding-top:62px;padding-bottom:66px}
.pill{display:inline-flex;align-items:center;gap:9px;background:#fff;border:1px solid var(--line);
  border-radius:999px;padding:7px 16px 7px 8px;font-size:13px;font-weight:500;color:var(--charcoal);
  box-shadow:var(--shadow);margin-bottom:20px}
.pill b{display:inline-flex;align-items:center;gap:6px;background:var(--butter);color:var(--charcoal);
  font-family:Poppins,sans-serif;font-weight:600;font-size:11px;letter-spacing:.06em;
  padding:4px 11px;border-radius:999px}
.pill b i{font-size:10px}
h1{font-size:clamp(32px,4.1vw,47px);margin-bottom:18px;max-width:19ch}
.hero-solo h1,.prose h1{max-width:24ch}
.h1-sm{font-size:clamp(30px,3.7vw,44px)}
.hero-lead{font-size:17.5px;color:var(--muted);max-width:52ch;margin-bottom:24px}
.ticks{display:flex;flex-wrap:wrap;gap:10px 22px;margin-bottom:26px}
.tick{display:flex;align-items:center;gap:8px;font-size:14px;color:var(--muted);font-weight:500}
.tick i{color:var(--mint-t);font-size:15px;flex-shrink:0}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg .ph{height:100%;border:0;border-radius:0;aspect-ratio:auto}
.hero-bg .ph-lab{inset:auto auto 18px 18px;align-items:flex-start;text-align:left;
  background:rgba(255,255,255,.82);border:1px solid #D8DCE1;border-radius:12px;padding:9px 13px;
  max-width:min(340px,52vw)}
.hero-bg .ph-lab i{display:none}
.hero-scrim{position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(100deg,rgba(250,249,246,.97) 0%,rgba(250,249,246,.90) 36%,
    rgba(250,249,246,.46) 56%,rgba(250,249,246,.12) 76%,rgba(250,249,246,0) 100%)}

/* trust chips (E-E-A-T, verified facts only) */
.chips{display:flex;flex-wrap:wrap;gap:9px;margin-top:4px}
.chip{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);
  border-radius:999px;padding:8px 15px;font-size:13px;font-weight:500;color:var(--charcoal);
  box-shadow:0 1px 2px rgba(62,65,69,.04)}
.chip i{font-size:13px;color:var(--lilac-t)}

/* ---------- lead form ---------- */
.qform{background:#fff;border:1px solid var(--line);border-radius:var(--rl);
  box-shadow:var(--shadow-lg);padding:24px;min-width:0}
.qf-top{display:flex;align-items:center;gap:11px;padding-bottom:15px;border-bottom:1px solid var(--line);
  margin-bottom:16px}
.qf-dot{width:36px;height:36px;border-radius:12px;background:var(--lilac);display:grid;place-items:center;
  flex-shrink:0;color:#fff;font-size:15px}
.qf-top>span:last-child{display:flex;flex-direction:column;min-width:0}
.qf-t{font-family:Poppins,sans-serif;font-weight:600;font-size:15px;line-height:1.3}
.qf-s{font-size:12.5px;color:var(--muted);line-height:1.35}
.qform form{display:grid;gap:13px;min-width:0}
.field{min-width:0}
.field>label{display:block;font-size:11.5px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;
  color:var(--muted);margin-bottom:6px}
.qform input,.qform select,.qform textarea{min-width:0;width:100%;border:1.5px solid var(--line);
  border-radius:13px;padding:12px 14px;font-size:14.5px;font-family:inherit;color:var(--charcoal);
  background:#FCFBFA;appearance:none}
.qform select{background-image:linear-gradient(45deg,transparent 50%,#6B7076 50%),
  linear-gradient(135deg,#6B7076 50%,transparent 50%);
  background-position:calc(100% - 19px) 21px,calc(100% - 14px) 21px;
  background-size:5px 5px,5px 5px;background-repeat:no-repeat;padding-right:38px}
.qform input:focus,.qform select:focus,.qform textarea:focus{outline:none;border-color:var(--lilac-t);
  box-shadow:0 0 0 3px rgba(214,198,230,.45)}
.qform textarea{resize:vertical;min-height:88px;line-height:1.55}
.qform textarea::placeholder,.qform input::placeholder{color:#82888F;font-size:13.6px;line-height:1.5}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:11px}
.frow>*{min-width:0}
.qform .btn{width:100%;margin-top:2px}
.qf-note{font-size:11.8px;color:var(--muted);text-align:center;line-height:1.5}
.req{color:var(--peach-t)}

/* ---------- trust strip ---------- */
.strip{background:var(--charcoal);color:#EDEEEF}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;
  padding-top:26px;padding-bottom:26px}
.strip div{min-width:0;display:flex;align-items:center;gap:11px;font-size:14.2px}
.strip i{font-size:19px;flex-shrink:0;color:var(--butter)}

/* ---------- tiles ---------- */
.tiles{display:grid;gap:18px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t6{grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}
.tile{min-width:0;display:block;border-radius:var(--rl);overflow:hidden;background:#fff;
  border:1px solid var(--line);transition:transform .2s ease, box-shadow .2s ease}
.tile:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
.tile .tb{padding:18px 18px 20px}
.tile b{display:block;font-family:Poppins,sans-serif;font-weight:600;font-size:16px;margin-bottom:4px}
.tile span{font-size:13.4px;color:var(--muted);display:block;line-height:1.5}
.t6 .tile .tb{padding:14px 14px 16px;text-align:center}
.t6 .tile b{font-size:14.5px}
.t6 .tile span{font-size:12.4px}
.tile>.tile-ic{display:flex;align-items:center;justify-content:center;height:74px;font-size:26px;
  background:#F6F3FB;color:var(--lilac-t);border-bottom:1px solid var(--line)}

/* ---------- cards ---------- */
.g2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.g3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.g4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.card{min-width:0;display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);
  border-radius:var(--rl);overflow:hidden;transition:transform .2s ease, box-shadow .2s ease;
  box-shadow:0 1px 2px rgba(62,65,69,.03)}
a.card:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg)}
.card .cb{padding:22px 24px 24px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:18px;margin-bottom:9px}
.card p{font-size:14.6px;color:var(--muted)}
.card .kw{margin-top:auto;padding-top:16px;font-size:13px;font-weight:600;color:var(--lilac-t);
  display:inline-flex;align-items:center;gap:7px}
.card-ic{display:flex;align-items:center;justify-content:center;height:96px;font-size:30px;
  background:#F6F3FB;color:var(--lilac-t);border-bottom:1px solid var(--line)}
.card-ic.sky{background:#EDF5FB;color:var(--sky-t)}
.card-ic.mint{background:#EEF7F2;color:var(--mint-t)}
.card-ic.butter{background:#FDF7E6;color:var(--butter-t)}
.card-ic.peach{background:#FDF1ED;color:var(--peach-t)}
.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
.tag{font-size:11.5px;font-weight:600;padding:4px 11px;border-radius:999px;background:#F2F3F5;color:var(--muted)}
.tag.p{background:#F4F0FA;color:var(--lilac-t)}
.tag.m{background:#EEF7F2;color:var(--mint-t)}
.tag.b{background:#FDF7E6;color:var(--butter-t)}
.tag.s{background:#EDF5FB;color:var(--sky-t)}

/* ---------- prose ---------- */
.prose{max-width:74ch}
.wrap>.prose{margin-left:auto;margin-right:auto}
.prose h2{font-size:clamp(24px,3vw,32px);margin:38px 0 14px}
.prose h3{font-size:19.5px;margin:28px 0 10px}
.prose p{margin-bottom:15px;color:var(--muted)}
.prose p strong{color:var(--charcoal)}
ul.b{display:grid;gap:11px;margin:0 0 18px;padding:0;list-style:none}
ul.b li{display:flex;gap:12px;color:var(--muted);font-size:15.6px;line-height:1.6}
ul.b li>i{color:var(--mint-t);font-size:15px;flex-shrink:0;margin-top:5px}
ul.b li>span{display:block;min-width:0}
ol.n{counter-reset:s;display:grid;gap:13px;margin:0 0 18px;padding:0;list-style:none}
ol.n li{display:flex;gap:13px;color:var(--muted);font-size:15.6px;line-height:1.6}
ol.n li::before{counter-increment:s;content:counter(s);flex-shrink:0;width:26px;height:26px;
  border-radius:8px;background:#F4F0FA;color:var(--lilac-t);display:grid;place-items:center;
  font-family:Poppins,sans-serif;font-weight:600;font-size:13px;margin-top:2px}
.card ul.b li{font-size:14.6px}
.prose a{color:var(--lilac-t);font-weight:600;text-decoration:underline;text-underline-offset:2px}

/* ---------- steps ---------- */
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.step{min-width:0;background:#fff;border:1px solid var(--line);border-radius:var(--rl);padding:28px 26px}
.step .n{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;
  font-family:Poppins,sans-serif;font-weight:700;font-size:18px;margin-bottom:16px}
.step h3{font-size:19px;margin-bottom:9px}
.step p{font-size:14.6px;color:var(--muted)}

/* ---------- split band ---------- */
.urg{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:38px;align-items:center;
  background:#FDF7E6;border:1px solid #F5E9C4;border-radius:var(--rl);overflow:hidden}
.urg.lilac{background:#F4F0FA;border-color:#EAE2F4}
.urg.sky{background:#EDF5FB;border-color:#DFEBF5}
.urg.mint{background:#EEF7F2;border-color:#DCEDE4}
.urg-txt{padding:40px 8px 40px 40px;min-width:0}
.urg h2{font-size:clamp(24px,3vw,34px);margin-bottom:14px}
.urg p{color:var(--muted);font-size:16px;margin-bottom:18px}
.urg .when{display:grid;gap:10px;margin-bottom:22px}
.urg .when div{display:flex;gap:11px;align-items:flex-start;font-size:14.6px;min-width:0;color:var(--muted)}
.urg .when i{font-size:15px;flex-shrink:0;margin-top:5px;color:var(--butter-t)}
.urg.lilac .when i{color:var(--lilac-t)}.urg.sky .when i{color:var(--sky-t)}.urg.mint .when i{color:var(--mint-t)}
.urg .when strong{color:var(--charcoal)}
.urg-img{min-width:0;height:100%}
.urg-img .ph{height:100%;min-height:280px;border-radius:0;border-width:0}

/* ---------- why ---------- */
.why{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:44px;align-items:center;
  background:#EDF5FB;border:1px solid #DFEBF5;border-radius:var(--rl);overflow:hidden}
.why-img{min-width:0;height:100%}
.why-img .ph{height:100%;min-height:340px;border-radius:0;border-width:0}
.why-txt{padding:44px 44px 44px 0;min-width:0}
.why-list{display:grid;gap:22px;margin-top:26px}
.why-i{display:flex;gap:15px;min-width:0}
.why-i .ic{width:44px;height:44px;border-radius:14px;background:#fff;display:grid;place-items:center;
  flex-shrink:0;font-size:18px;color:var(--sky-t)}
.why-i h3{font-size:16.5px;margin-bottom:5px}
.why-i p{font-size:14.2px;color:var(--muted)}

/* ---------- comparison table ---------- */
.tblw{overflow-x:auto;border:1px solid var(--line);border-radius:var(--rl);background:#fff}
table.cmp{border-collapse:collapse;width:100%;min-width:560px;font-size:14.6px}
table.cmp th{background:#F6F3FB;text-align:left;padding:14px 18px;font-family:Poppins,sans-serif;
  font-weight:600;font-size:13px;color:var(--charcoal);border-bottom:1px solid var(--line)}
table.cmp td{padding:13px 18px;border-bottom:1px solid var(--line);color:var(--muted);vertical-align:top}
table.cmp tr:last-child td{border-bottom:0}
table.cmp td:first-child{color:var(--charcoal);font-weight:600}

/* ---------- locations ---------- */
.loc-band{background:#F4F0FA;border-radius:var(--rl);padding:38px 34px;border:1px solid #EAE2F4}
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;margin-top:26px}
.loc-col{min-width:0}
.loc-col h3{font-size:16.5px;margin-bottom:4px}
.loc-col .st{font-size:12px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;
  color:var(--muted);margin-bottom:12px;display:block}
.loc-col a{display:block;font-size:14.2px;color:var(--charcoal);padding:5px 10px;border-radius:9px;
  overflow-wrap:anywhere}
.loc-col a:hover{background:#fff;color:var(--lilac-t)}
.loc-note{margin-top:26px;padding-top:22px;border-top:1px solid #E3D9F0;font-size:14px;color:var(--muted)}
.loc-inline{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.loc-inline a,.loc-inline span{background:#fff;border:1px solid #E6DDF3;border-radius:999px;padding:6px 14px;
  font-size:13px;font-weight:500;color:var(--charcoal)}
.loc-inline a:hover{background:var(--lilac);border-color:var(--lilac)}
.loc-inline span{color:var(--muted);background:#FBFAFD}

/* ---------- faq ---------- */
.faq{max-width:860px;margin:0 auto}
.faq details{background:#fff;border:1px solid var(--line);border-radius:var(--r);margin-bottom:12px;
  overflow:hidden}
.faq details[open]{border-color:var(--lilac);box-shadow:var(--shadow)}
.faq summary{cursor:pointer;list-style:none;padding:20px 56px 20px 24px;position:relative;
  font-family:Poppins,sans-serif;font-weight:600;font-size:16.5px;color:var(--charcoal)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"";position:absolute;right:24px;top:26px;width:11px;height:11px;
  border-right:2.4px solid var(--lilac-t);border-bottom:2.4px solid var(--lilac-t);
  transform:rotate(45deg);transition:transform .22s ease}
.faq details[open] summary::after{transform:rotate(-135deg);top:29px}
.faq .ans{padding:0 24px 22px;font-size:15.2px;color:var(--muted)}
.faq .ans p{margin-bottom:12px}.faq .ans p:last-child{margin-bottom:0}
.faq .ans a{color:var(--lilac-t);font-weight:600;text-decoration:underline;text-underline-offset:2px}

/* ---------- cta band ---------- */
.band{position:relative;border-radius:var(--rl);overflow:hidden;border:1px solid #EAE2F4;
  background:linear-gradient(135deg,#F4F0FA 0%,#EDF5FB 52%,#FDF1ED 100%)}
.band-in{position:relative;z-index:2;padding:60px 44px;text-align:center}
.band h2{font-size:clamp(26px,3.4vw,40px);margin-bottom:16px}
.band p{color:var(--muted);font-size:17px;max-width:56ch;margin:0 auto 28px}
.cta-row{display:flex;flex-wrap:wrap;gap:13px}
.band .cta-row{justify-content:center}

/* ---------- footer ---------- */
footer{background:var(--charcoal);color:#D9DBDE;padding-top:64px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:34px;
  padding-bottom:44px;border-bottom:1px solid rgba(255,255,255,.11)}
.f-brand{min-width:0}
.f-brand .brand-sub{color:#fff}
.f-brand p{font-size:14.2px;color:#A9ADB2;margin:16px 0 18px;max-width:34ch}
.f-col{min-width:0}
.f-col h3{font-family:Poppins,sans-serif;font-weight:600;font-size:12px;letter-spacing:.13em;
  text-transform:uppercase;color:#fff;margin-bottom:14px}
.f-col li{margin-bottom:8px}
.f-col a{font-size:14px;color:#A9ADB2;overflow-wrap:anywhere}
.f-col a:hover{color:var(--butter);text-decoration:underline}
.f-bot{display:flex;flex-wrap:wrap;gap:14px 26px;align-items:center;justify-content:space-between;
  padding:24px 0 30px;font-size:13.2px;color:#9AA0A6}
.f-bot a:hover{color:var(--butter);text-decoration:underline}
.f-bar{background:var(--lilac);color:var(--charcoal);text-align:center;padding:14px 20px;
  font-size:13.5px;font-weight:500;display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:wrap}

/* ---------- sticky mobile bar ---------- */
.sticky{display:none}

/* ---------- thank you / status pages ---------- */
.ty{max-width:680px;margin:0 auto;text-align:center;padding-top:70px;padding-bottom:70px}
.ty-mark{width:88px;height:88px;border-radius:50%;background:var(--mint);display:grid;place-items:center;
  margin:0 auto 26px;font-size:36px;color:var(--charcoal)}
.ty h1{font-size:clamp(30px,4vw,44px);margin-bottom:16px}
.ty>p{color:var(--muted);font-size:17.5px;margin-bottom:28px}
.ty-next{background:#fff;border:1px solid var(--line);border-radius:var(--rl);padding:28px;text-align:left;
  margin-bottom:28px;box-shadow:var(--shadow)}
.ty-next h2{font-size:19px;margin-bottom:18px}
.ty-next ol{margin:0;padding:0;list-style:none;display:grid;gap:16px}
.ty-next li{display:flex;gap:14px;font-size:15px;color:var(--muted);min-width:0}
.ty-next li b{width:28px;height:28px;border-radius:9px;background:#F4F0FA;
  color:var(--lilac-t);display:grid;place-items:center;font-family:Poppins,sans-serif;font-size:13.5px;flex-shrink:0}
.ty-next li span{display:block;min-width:0}
.ty-next li strong{color:var(--charcoal);display:block;font-weight:600}

/* ---------- legal ---------- */
.legal{display:grid;grid-template-columns:250px minmax(0,1fr);gap:48px;align-items:start}
.legal-toc{position:sticky;top:100px;background:#fff;border:1px solid var(--line);border-radius:var(--r);
  padding:20px}
.legal-toc h2{font-family:Poppins,sans-serif;font-size:11.5px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--muted);margin-bottom:12px}
.legal-toc a{display:block;font-size:13.6px;color:var(--charcoal);padding:6px 9px;border-radius:9px;line-height:1.4}
.legal-toc a:hover{background:#F5F1FA;color:var(--lilac-t)}
.note{background:#FDF7E6;border:1px solid #F5E9C4;border-radius:var(--r);padding:18px 20px;
  font-size:14.4px;color:var(--muted);display:flex;gap:13px;margin-bottom:26px}
.note i{color:var(--butter-t);font-size:16px;flex-shrink:0;margin-top:3px}
.note strong{color:var(--charcoal)}

/* ================= responsive ================= */
@media (max-width:1440px){
  .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:13.4px}
}
@media (max-width:1280px){
  .burger{display:grid;place-items:center;width:44px;height:44px;border-radius:13px;
    border:1px solid var(--line);background:#fff;cursor:pointer;margin-left:auto;flex-shrink:0;
    font-size:17px;color:var(--charcoal)}
  .hdr-cta{display:none}
  .hdr-act{margin-left:12px}
  .nav{position:fixed;top:78px;left:0;right:0;bottom:0;margin:0;background:var(--white);
    display:block;overflow-y:auto;padding:18px var(--gut) 40px;
    clip-path:inset(0 0 0 100%);pointer-events:none;opacity:0;
    transition:clip-path .3s ease, opacity .25s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:15px 4px;font-size:16px;font-weight:600;border-radius:0;justify-content:space-between}
  .nav .caret{font-size:13px}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    border-radius:0;padding:0 0 12px;min-width:0;max-height:0;overflow:hidden;transition:max-height .3s ease}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 12px;font-size:14.6px;color:var(--muted)}
  .nav-cta{display:flex!important;flex-direction:column;gap:11px;padding-top:22px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid,.hero-split{grid-template-columns:minmax(0,1fr);gap:38px;padding-top:44px;padding-bottom:54px}
  .hero-scrim{background:linear-gradient(180deg,rgba(250,249,246,.62) 0%,rgba(250,249,246,.93) 26%,rgba(250,249,246,.98) 100%)}
  .hero-form{max-width:560px}
  .t6{grid-template-columns:repeat(3,minmax(0,1fr))}
  .t4,.g3,.g4,.steps{grid-template-columns:repeat(2,minmax(0,1fr))}
  .urg,.why{grid-template-columns:minmax(0,1fr)}
  .urg-txt{padding:34px 30px 8px}
  .urg-img .ph{min-height:240px}
  .why-txt{padding:8px 32px 38px}
  .why-img{order:-1}
  .why-img .ph{min-height:260px}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
  .legal{grid-template-columns:minmax(0,1fr);gap:28px}
  .legal-toc{position:static}
}
@media (max-width:768px){
  :root{--gut:26px}
  .sec{padding-top:60px;padding-bottom:60px}
  .sec-tight{padding-top:48px;padding-bottom:48px}
  body{font-size:16px}
  .nav{top:70px}
  .hdr{min-height:70px}
  .loc-band,.band-in{padding:32px 24px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(250,249,246,.97);backdrop-filter:blur(10px);border-top:1px solid var(--line);
    padding:10px 14px calc(10px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:13px 12px;font-size:14.2px}
  footer{padding-bottom:74px}
}
@media (max-width:600px){
  .t6,.t4,.t3,.g2,.g3,.g4,.steps,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:14px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:26px}
}
@media (max-width:430px){
  :root{--gut:20px}
  .card .cb,.step,.qform,.ty-next{padding:22px}
  .brand-mark{width:34px;height:34px}
  .brand-kids{font-size:15.5px}
  .brand-sub{font-size:9.5px}
  .cta-row .btn{width:100%}
}


.nifty-totop{position:fixed;z-index:2147482000;bottom:22px;right:22px;width:48px;height:48px;display:flex;align-items:center;justify-content:center;padding:0;border:0;cursor:pointer;background:#111827;color:#ffffff;border-radius:50%;box-shadow:0 6px 20px rgba(0,0,0,.22);opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .25s ease,transform .25s ease,visibility .25s;-webkit-tap-highlight-color:transparent}.nifty-totop svg{width:52%;height:52%;display:block}.nifty-totop:hover{filter:brightness(1.08)}.nifty-totop:focus-visible{outline:2px solid #ffffff;outline-offset:2px}.nifty-totop.nifty-totop-on{opacity:1;visibility:visible;transform:none}@media print{.nifty-totop{display:none!important}}
